from collections import deque

def longest_cycle(roads):
    n, m = len(roads) + 1, len(roads) + 1
    graph = [[] for _ in range(n)]

    for u, v in roads:
        graph[u].append(v)

    longest = -1

    for i in range(1, n):
        visited = [False] * n
        visited[i] = True
        stack = deque([i])

        while stack:
            current = stack.pop()
            visited[current] = False

            for neighbor in graph[current]:
                if visited[neighbor]:
                    longest = max(longest, len(visited[neighbor:]) - 1)
                else:
                    visited[neighbor] = True
                    stack.append(neighbor)

    return longest > 0

def find_intersection(roads, intersections):
    longest_key = -1
    longest_value = 0

    for key, values in intersections.items():
        if values > longest_value:
            longest_value = values
            longest_key = key

    return longest_key

