import math

def min_val(u, v, b, d):
    if b > u[u.index(v)]:
        u[u.index(v)] = b
        d[(v - 1) // u[v - 1]] = 1
    elif b < u[u.index(v)]:
        u[u.index(v)] = b
        d[(v - 1) // u[v - 1]] = 2
    return d[(v - 1) // u[v - 1]]

def game_runner(u, v, x, turn, count):
    if count == 0:
        winner = 0
    total = 0
    while True:
        min_b = min(u[1:v + 1])
        index = u.index(min_b)
        turn = index//u[v-x]
        total += count * d[count] * min(v-x, (u[v-x] - min_b))
        if turn == 0:
            min_val(u, index, min_b, count)
        else:
            max_val(u, index, min_b)
        if count == 0:
            if total <= 0:
                winner = 1
            elif total <= min_b:
                winner = 2
            else:
                winner = 0
                break
        break
    return winner, count
