from collections import defaultdict
import math
from itertools import permutations

def solve(n, k):
    colors = []
    for i in range(n):
        A, C = map(int, input().split())
        colors.append((A, C))

    expected_colorfulness = 0
    for _, row in groupby(sorted(colors, key=lambda x: x[1]), lambda x: x[1]):
        colors, cnt = list(row), defaultdict(int)
        for _, c in row:
            cnt[c] += 1
        max_colors = len(cnt)
        if max_colors > 2:
            max_diff = (-1.0 /  ((max_colors - 1) * (max_colors - 2) / 6)) * 2
        else:
            max_diff = -1.0 / ((len(cnt) - 1) * 2)
        ba = fibo(n)  # Bell numbers to accommodate n
        expected_colorfulness += ba[1] * max_diff  # Expected value is ba[1] * max_diff * 2/(2^n)
    return math.log(expected_colorfulness, 2)

def fibo(n):
