from math import sqrt

def is_prime(n):
    if n <= 1 or n % 2 == 0:
        return n == 2
    for i in range(3, int(sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def count_favorite_primes(S, M):
    favorite_primes = [prime for prime in S if is_prime(prime)]
    primes_squared = {prime: prime ** 2 for prime in favorite_primes}

    count = 0
    for number in range(1, M + 1):
        for prime in favorite_primes:
            if number % prime == 0:
                count += number // prime
                if number // prime in primes_squared:
                    count -= primes_squared[number // prime]
    return count

