from collections import defaultdict

def read_input():
    return [int(x) for x in input().split()]

def process(test_case_count):
    N = read_input()[0]
    tree = defaultdict(list)
    closest_to_target = defaultdict(list)
    for _ in range(N - 1):
        u, v, w = read_input()
        tree[u - 1].append((v - 1, w))
        tree[v - 1].append((u - 1, w))
    M = read_input()[0]
    vertices = set(range(N))
    min_times = [-1] * N

    def shortest_path(target, start):
        distances = {u: float('inf') for u in vertices}
        distances[start] = 0
        visited = {start}
        queue = [(0, start)]

        while queue:
            current_time, current = queue.pop(0)
            if current_time > 0:
                distances[current] = float('inf')
            for neighbor, distance in tree[current]:
                new_time = current_time + distance
                if new_time < distances[neighbor]:
                    distances[neighbor] = new_time
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((new_time, neighbor))
        return distances[target] + 1

    for _ in range(M):
        u, v, target_time, speed = read_input()
        u -= 1
        v -= 1

        visited_vertex = set()

        def bfs():
            nonlocal visited_vertex
            distancesv = {target: 0}
            queue = [('v', 0)] if u == v else [('u', 0)]
            while queue:
                current, current_time = queue.pop(0)
                for neighbor, distance in tree[neighbor]:
                    if abs(current_time - target_time) + distance < distancesv.get(neighbor, float('inf')):
                        visited_vertex.add(neighbor)
                        distancesv[neighbor] = abs(current_time - target_time) + distance
                        queue.append((neighbor, distance))
        bfs()

        min_time = float('inf')
        for vertex in visited_vertex:
            current_time = shortest_path(vertex, u)
            if current_time < min_time:
                min_time = current_time
            else:
                closest_to_target[vertex].append(current_time)

        for i, target_time_diff in enumerate(closest_to_target[vertex]):
            if target_time_diff == closest_to_target[u][i]:  # If the target times of the speedsters are the same
                if current_time == min_time:  # If the times of closest_to_target match
                    min_times[i] = target_time_diff  # Set it to the target time
                else:
                    min_times[i] = -1  # Set it to -1 if not equal
                    break

        if min_time == float('inf'):
            break  # If no speedster visits the vertex

        visited_vertices = set()
        for target_time_i, time_visit_intermediate_vertex in enumerate(closest_to_target[vertex]):
            if time_visit_intermediate_vertex >= min_times[target_time_i]:
                visited_vertices.add[target_time_i]

        visited_vertex |= visited_vertices

    return '\n'.join(['%.6f' % min_time for u, min_time in enumerate(min_times)])

def main():
    T = read_input()[0]
    tests = [process(T)]
    print('\n'.join(tests))

if __name__ == "__main__":
    main()
