from collections import defaultdict

def sort_array(arr, s):
    def count_length(cycle_length):
        count = 0
        num_occurrences = defaultdict(int)
        for i in range(len(arr)):
            num_occurrences[arr[i]] += 1
            if arr[i] in arr[: i + 1]:
                k = i
                while k < arr.index(arr[i]):
                    if cycle_length - (i - k) + 1 - num_occurrences[arr[k]] < s:
                        count += cycle_length - (i - k)
                        cycle_length -= cycle_length - (i - k) + 1 - num_occurrences[arr[k]]
                    num_occurrences[arr[k]] -= 1
                    k += 1
        return count

    cache = {}

    def backtrack_helper(start, operations, sum_coins):
        if start == len(arr):
            return 0
        if (start, frozenset(operations), frozenset(arr[start:])) in cache:
            return cache[(start, frozenset(operations), frozenset(arr[start:]))]

        best = float('inf')
        for length in range(1, len(arr) - start + 1):
            candies_to_put = count_length(length)
            if sum_coins + candies_to_put <= s:
                operations.append(length)
                best = min(best, backtrack_helper(start + length, operations, sum_coins + candies_to_put))
                operations.pop()
        cache[(start, frozenset(operations), frozenset(arr[start:]))] = best
        return best

    start = 0
    result = backtrack_helper(start, [], 0)
    return len(operations[:-1]) if result != float('inf') else -1

