                min_length = min(min_length, dp[j])
        dp[i] = min_length + 1

    min_length = float('inf')
    for i in range(size):
        if dp[i] < min_length:
            min_length = dp[i]

    return min_length if size > 1 else float('inf')

def cycle_lengths(seq):
    n = len(seq)
    lengths = []
    for i in range(n):
        idx = seq.index(i + 1)
        new_seq = seq[idx:] + seq[:idx]
        min_length = find_shortest_cycle_length(new_seq)
        if len(lengths) == n:
            min_length = min(min_length, find_shortest_cycle_length(seq))
        if min_length == n:
            return {"error" : True}
        lengths.append(min_length)
        seq = new_seq
    return {"error": False, "amount": sum(lengths)}

