import itertools

def colorfulness(A, C, P):
    N = len(A)
    sum_color = 0
    for i in range(N):
        if P[i] - i == 1:
            sum_color += sum(C[P[j]] == C[P[j+1]] for j in range(i, N-1) if P[j] > P[j+1])
    return sum_color

def expected_colorfulness(A, C, n, k):
    total_permutations = math.factorial(n)
    blocks_count = {}
    for i in range(n):
        if C[i] not in blocks_count:
            blocks_count[C[i]] = [(i, 0)]
        else:
            blocks_count[C[i]].append((i, blocks_count[C[i]][-1][1] + 1))
    perm = itertools.permutations(blocks_count)
    expected = 0
    for perm_ in perm:
        C_ = [b[-1][0] for b in perm_]
        count = 0
        for i in range(n-1):
            count += 1 if C_[i].value == C_[i+1].value else 0
        if C_[k-1].value == C_[n-1].value:
            expected += count
    return expected / total_permutations

