import math

def is_prime(num):
    """Check if a number is prime."""
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def find_numbers(up_to):
    """Find number of factors for all numbers up to the limit."""
    return (up_to + 1) * (up_to // 2)

def count_numbers(s, up_to):
    """Count numbers of the form x that are less than or equal to 'up_to' which have some number of prime factors in 's'."""
    count_x = 0
    for prime in s:
        factor_count = 0
        while prime <= up_to:
            if up_to % prime == 0:
                factor_count += 1
                up_to //= prime
            else:
                prime += 1
        # multiply the factors, then minus two multiplying factors since for two same prime factor it is added twice.
        total = count_x + factor_count / 2 - (2 if factor_count % 2 else 0)
        count_x = total
    return int(count_x)

