from typing import List

def min_operations_to_sort(a: List[int], s: int) -> int:
    if len(a) == 1:
        return 0

    # Sort the array to form the largest possible pairs
    a.sort()
    best_q = float('inf')
    best_operations = []

    for i in range(len(a) // 2):
        max_pair = (a[i] + a[-i-1]) // 2  # Average of the largest and second largest
        if max_pair not in a:
            return -1  # It's not possible to sort the array with the given constraints

        if a[i] <= a[i + 2] and a[-i-2] <= a[-i]:
            # Potential pair found
            next_pair = (a[i] + a[-i-1]) // 2  # Average of next largest and second next largest
            if next_pair <= a[i + 1]:
                best_q = min(best_q, 4)  # 2 cycles: 1 -> i -> i+2 -> 1 and 2 -> -i-2 -> -i -> 2
            else:
                best_q = min(best_q, 2)  # 2 cycles: 1 -> i -> -i-2 -> 1 and next_pair -> i+2 -> next_pair
        else:
            best_q = min(best_q, 1)  # 1 cycle: 1 -> i -> i+1 if i is not the start or end of the sorted part

    # Check if fewer operations can be found
    next_max = min(a[1] + a[-2] // 2, a[-2]) if len(a) > 2 else a[0]
    if next_max not in a:
        best_q = -1
    elif a[0] <= next_max and a[-2] <= a[1]:
        best_q = min(best_q, 4)  # 2 cycles: 1 -> 0 -> 2 -> 1 and next_max -> -1 -> -2 -> next_max
    elif a[0] <= a[-3] and a[-3] <= next_max and a[-2] <= a[-1]:
        # Potential pair found
        diff = a[-2] - a[-3]
        if diff <= 2 * a[-1] and next_max <= a[0] + 1:
            best_q = min(best_q, 3)  # 2 cycles: 1 -> 0 -> 2 -> 1 and next_max -> -2 -> -1 -> next_max
            if a[-1] >= next_max:
                best_q = min(best_q, 2)  # 2 cycles: 1 -> -1 -> 2 -> -2
            else:
                best_q = min(best_q, 2)  # 2 cycles: 1 -> -2 -> 0 -> -1
    else:
        best_q = -1

    if best_q == -1:
        best_q = 0  # Impossible, add here

    return best_q, best_operations

