def bellman_ford(n, edges):
    distance = [float('inf')] * n
    distance[0] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if distance[u] != float('inf') and distance[u] + w < distance[v]:
                distance[v] = distance[u] + w
    return distance

def find_min_time(n, M, edges, vertices, speedsters):
    distance = bellman_ford(n, edges)
    for u, v, t, s in speedsters:
        if distance[u] + s < distance[v]:
            distance[v] = distance[u] + s
    return distance

