def ultimate_weirdness(nums: List[int]) -> int:
    def remove(aL: int, bR: int) -> int:
        if aL == bR:
            return nums[aL] 
        mid = (aL + bR) // 2
        return remove(aL, mid) * remove(mid + 1, bR) // gcd(remove(aL, mid), remove(mid + 1, bR))

    def weirdness(nums: List[int]) -> int:
        if len(nums) <= 1:
            return 0
        firstValid = 1
        for i in range(len(nums)):
            if nums[i] != 0:
                firstValid = i
                break
        nums = df(nums)
        oddNums = nums[firstValid:]
        oddGcd = oddNums[0]
        total = firstValid
        while total < len(oddNums):
            prev = oddGcd
            for i in range(total, min(total + 3, len(oddNums))):
                oddGcd = gcd(oddGcd, oddNums[i])
                if oddGcd != oddNums[i]:
                    break
            if oddGcd > 1 and oddNums[total] != oddNums[prev]:
                return firstValid * (total - 1)
            elif len(oddNums[total:]) == 1 or len(oddNums) - total + 1 + gcd(oddNums[total:], oddNums) == len(oddNums):
                total = len(oddNums)
                continue
            else:
                return (N - firstValid) * (oddNums[total - 1] - firstValid)
        return firstValid + (N - firstValid) * (total - 1)

