def find_intersection(n, m, edges):
    # Create directed graph
    adj = {i: [] for i in range(1, n+1)}
    for u, v in edges:
        adj[u].append(v)
    # Topological sort from all sources (intersection source)
    queue = [i for i in range(n+1) if i not in adj]
    seen = [False] * (n + 1)
    order = []

    while queue:
        node = queue.pop()
        order.append(node)
        seen[node] = True
        for neighbor in adj[node]:
            adj[neighbor].remove(node)
            if not seen[neighbor]:
                queue.append(neighbor)

    return order[-1] if all(seen) else -1
