from math import gcd
from itertools import islice

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def still_mercury(n, mercury):
    factors = prime_factors(n)
    for prime in factors:
        if gcd(n, prime) > mercury:
            return False
    return True

